"""Invoice/installment checks with a review-only forecast download."""
HTML='''<section class="card files-section"><h2>VENTAS, VENCIMIENTOS Y PREVISIÓN DE COBROS</h2><p>Recibe por separado las líneas de venta ampliadas y sus cuotas. Puedes usar dos hojas de un mismo Excel, leyendo y guardando cada hoja con su contenido. En Expedientes recibidos, marca ventas, vencimientos y las previsiones que quieras contrastar del mismo expediente y corte.</p><p>Los descuentos se comprueban contra el neto ya declarado, sin restarlos otra vez. El IVA usa el tipo o importe que aportes. Para conciliar se necesita un total de factura documentado único y el saldo pendiente de cada cuota.</p><button id="sales-receivables-check" type="button">Conciliar ventas, cuotas y cobros marcados</button><p id="sales-receivables-summary" class="files-notice" role="status"></p><div id="sales-receivables-results"></div><div class="files-actions"><button id="sales-receivables-prev" type="button" disabled>Anterior</button><button id="sales-receivables-next" type="button" disabled>Siguiente</button></div><label><input id="sales-receivables-ack" type="checkbox" style="display:inline;width:auto"> He revisado el resultado. Descargaré únicamente cobros nuevos de facturas conciliadas, como borrador pendiente de carga y revisión.</label><button id="sales-receivables-export" type="button" class="primary" disabled>Descargar previsión de cobros preparada (.csv)</button><p>La descarga conserva referencias de cliente, factura y cuota, con identificadores estables. Excluye cuotas cobradas y cobros ya vinculados; una posible coincidencia sin vínculo queda pendiente. El CSV se recibe después como Previsión de cobros y pagos. No se añade automáticamente a tesorería ni acredita capacidad de compra.</p><p id="sales-receivables-notice" class="files-notice" role="status"></p></section>'''
JS=r'''
let salesReceivablesReport=null,salesReceivablesSequence=0,salesReceivablesPage=0;
function invalidateSalesReceivables(){salesReceivablesSequence++;salesReceivablesReport=null;salesReceivablesPage=0;$('sales-receivables-results').replaceChildren();$('sales-receivables-summary').textContent='';$('sales-receivables-ack').checked=false;$('sales-receivables-export').disabled=true;$('sales-receivables-prev').disabled=true;$('sales-receivables-next').disabled=true}
function renderSalesReceivables(){const r=salesReceivablesReport;if(!r)return;const container=$('sales-receivables-results');container.replaceChildren();const rows=r.invoices.slice(salesReceivablesPage*50,(salesReceivablesPage+1)*50);rows.forEach(i=>{const card=document.createElement('details');card.className='files-subpanel';const summary=document.createElement('summary');summary.textContent=i.customer_id+' · '+i.invoice_number+' · '+i.currency+' · '+(i.status==='RECONCILED'?'Importes conciliados':'REVISAR');card.append(summary);const totals=document.createElement('p');totals.textContent='Neto: '+money(i.net_amount)+' · IVA: '+money(i.vat_amount)+' · Total calculado de líneas: '+money(i.computed_gross_total)+' · Total documentado de factura: '+money(i.documented_invoice_total)+' · Suma de cuotas originales: '+money(i.installment_total)+'.';card.append(totals);const basis=document.createElement('p');basis.textContent=i.vat_basis.includes('CALCULATED_FROM_DECLARED_RATE')?'Hay IVA calculado a partir del tipo declarado; no se presenta como una cuota documental original.':'IVA según los importes documentados aportados o pendiente si falta.';card.append(basis);i.issues.forEach(issue=>{const p=document.createElement('p');p.textContent=issue.message;card.append(p)});const box=document.createElement('div');box.id='sales-receivables-quota-'+container.children.length;box.className='scroll';card.append(box);container.append(card);const labels={NO_PENDING_COLLECTION:'Sin pendiente',ALREADY_IN_FORECAST:'Ya está en previsión',NEW_DRAFT_COLLECTION:'Cobro nuevo para borrador',BLOCKED_BY_INVOICE_REVIEW:'Pendiente de conciliar factura',REVIEW_REQUIRED:'Revisar vínculo o datos'};receptionTable(box.id,['Cuota / referencia','Vencimiento','Original','Pendiente al corte','Forma de cobro','Resultado','Origen'],i.quotas.map(q=>[q.installment_number+' · '+q.installment_ref,stockDate(q.due_date),money(q.amount),money(q.pending_amount),q.payment_method,labels[q.status]||'Revisar',q.source.filename+' · fila '+q.source.row]));const sources=document.createElement('small');sources.textContent='Líneas de venta: '+i.line_sources.map(s=>s.filename+' · fila '+s.row).join(' · ');card.append(sources)});$('sales-receivables-prev').disabled=salesReceivablesPage===0;$('sales-receivables-next').disabled=(salesReceivablesPage+1)*50>=r.invoices.length}
$('sales-receivables-prev').onclick=()=>{salesReceivablesPage--;renderSalesReceivables()};$('sales-receivables-next').onclick=()=>{salesReceivablesPage++;renderSalesReceivables()};$('sales-receivables-ack').onchange=()=>{$('sales-receivables-export').disabled=!salesReceivablesReport?.ticket||!$('sales-receivables-ack').checked};
$('sales-receivables-check').onclick=async()=>{invalidateSalesReceivables();const sequence=salesReceivablesSequence,batch_ids=[...$('received-batches').querySelectorAll('input:checked')].map(x=>x.value);$('sales-receivables-check').disabled=true;$('sales-receivables-notice').textContent='Comprobando líneas, cuotas y cobros existentes…';try{const r=await api('/api/reception/sales-reconcile',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({batch_ids})});if(sequence!==salesReceivablesSequence)return;salesReceivablesReport=r;$('sales-receivables-summary').textContent=r.legal_name+' · corte '+stockDate(r.as_of_date)+' · '+r.invoice_count+' facturas · '+r.issue_count+' comprobaciones pendientes · '+r.candidate_count+' cobros nuevos preparables. '+(r.candidate_count>r.export_limit?'Acota la selección a un máximo de '+r.export_limit+' cobros para descargar.':'Solo se exportan facturas conciliadas.');renderSalesReceivables();$('sales-receivables-notice').textContent=r.candidate_count?'Revisa los importes y los motivos pendientes. La descarga no carga ni activa estos cobros.':'No hay cobros nuevos descargables: revisa los avisos o comprueba si las cuotas ya están cobradas o vinculadas.'}catch(e){if(sequence===salesReceivablesSequence)$('sales-receivables-notice').textContent=e.message}finally{$('sales-receivables-check').disabled=false}};
$('sales-receivables-export').onclick=async()=>{if(!salesReceivablesReport?.ticket||!$('sales-receivables-ack').checked)return;const sequence=salesReceivablesSequence;$('sales-receivables-export').disabled=true;try{const r=await api('/api/reception/sales-collections/export',{method:'POST',headers:{'Content-Type':'application/json','X-EIOS-Token':token},body:JSON.stringify({ticket:salesReceivablesReport.ticket,acknowledge_draft:true})});if(sequence!==salesReceivablesSequence)return;const bytes=Uint8Array.from(atob(r.content_base64),c=>c.charCodeAt(0)),blob=new Blob([bytes],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=r.filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);salesReceivablesReport.ticket=null;$('sales-receivables-notice').textContent=r.record_count+' cobros nuevos descargados como borrador. '+r.excluded_invoice_count+' facturas pendientes excluidas. Recíbelo después como Previsión de cobros y pagos; no se ha modificado tesorería.'}catch(e){if(sequence===salesReceivablesSequence)$('sales-receivables-notice').textContent=e.message}};
'''
